#if IS_SDLv1
static PyObject *
pg_event_get(PyObject *self, PyObject *args)
{
    SDL_Event event;
    int mask = 0;
    int loop, num;
    PyObject *type, *list, *e;
    int val;

    if (PyTuple_Size(args) != 0 && PyTuple_Size(args) != 1)
        return RAISE(PyExc_ValueError, "get requires 0 or 1 argument");

    VIDEO_INIT_CHECK();

    if (PyTuple_Size(args) == 0)
        mask = SDL_ALLEVENTS;
    else {
        type = PyTuple_GET_ITEM(args, 0);
        if (PySequence_Check(type)) {
            num = PySequence_Size(type);
            for (loop = 0; loop < num; ++loop) {
                if (!pg_IntFromObjIndex(type, loop, &val))
                    return RAISE(
                        PyExc_TypeError,
                        "type sequence must contain valid event types");
                mask |= SDL_EVENTMASK(val);
            }
        }
        else if (pg_IntFromObj(type, &val))
            mask = SDL_EVENTMASK(val);
        else
            return RAISE(PyExc_TypeError,
                         "get type must be numeric or a sequence");
    }

    list = PyList_New(0);
    if (!list)
        return NULL;

    SDL_PumpEvents();

    while (SDL_PeepEvents(&event, 1, SDL_GETEVENT, mask) == 1)
    {
        e = pgEvent_New(&event);
        if (!e) {
            Py_DECREF(list);
            return NULL;
        }

        PyList_Append(list, e);
        Py_DECREF(e);
    }
    return list;
}
#else /* IS_SDLv2 */
static PG_INLINE int
_pg_event_append_to_list(PyObject *list, SDL_Event *event)
{
    PyObject *e = pgEvent_New(event);
    if (!e) {
        Py_DECREF(list);
        return 0;
    }
    PyList_Append(list, e);
    Py_DECREF(e);
    return 1;
}

static PyObject *
pg_event_get(PyObject *self, PyObject *args)
{
    SDL_Event event;
    int loop, num;
    PyObject *type, *list;
    int val;

    if (PyTuple_Size(args) != 0 && PyTuple_Size(args) != 1)
        return RAISE(PyExc_ValueError, "get requires 0 or 1 argument");

    VIDEO_INIT_CHECK();

    list = PyList_New(0);
    if (!list)
        return NULL;
    SDL_PumpEvents();

    if (PyTuple_Size(args) == 0) {
        while (SDL_PeepEvents(&event, 1, SDL_GETEVENT, SDL_FIRSTEVENT, SDL_LASTEVENT) == 1) {
            if(!_pg_event_append_to_list(list, &event))
                return NULL;
        }
        return list;
    }

    type = PyTuple_GET_ITEM(args, 0);
    if (PySequence_Check(type)) {
        num = PySequence_Size(type);
        for (loop = 0; loop < num; ++loop) {
            if (!pg_IntFromObjIndex(type, loop, &val)) {
                Py_DECREF(list);
                return RAISE(
                    PyExc_TypeError,
                    "type sequence must contain valid event types");
            }
            if (SDL_PeepEvents(&event, 1, SDL_GETEVENT, val, val) < 0) {
                Py_DECREF(list);
                return RAISE(pgExc_SDLError, SDL_GetError());
            }
            if(!_pg_event_append_to_list(list, &event))
                return NULL;
        }
    }
    else if (pg_IntFromObj(type, &val)) {
        if (SDL_PeepEvents(&event, 1, SDL_GETEVENT, val, val) < 0) {
            Py_DECREF(list);
            return RAISE(pgExc_SDLError, SDL_GetError());
        }
        if(!_pg_event_append_to_list(list, &event))
            return NULL;
    }

    Py_DECREF(list);
    return RAISE(PyExc_TypeError,
                 "get type must be numeric or a sequence");
}
#endif /* IS_SDLv2 */

#if IS_SDLv1
static PyObject *
pg_event_peek(PyObject *self, PyObject *args)
{
    SDL_Event event;
    int result;
    int mask = 0;
    int loop, num, noargs = 0;
    PyObject *type;
    int val;

    if (PyTuple_Size(args) != 0 && PyTuple_Size(args) != 1)
        return RAISE(PyExc_ValueError, "peek requires 0 or 1 argument");

    VIDEO_INIT_CHECK();

    if (PyTuple_Size(args) == 0) {
        mask = SDL_ALLEVENTS;
        noargs = 1;
    }
    else {
        type = PyTuple_GET_ITEM(args, 0);
        if (PySequence_Check(type)) {
            num = PySequence_Size(type);
            for (loop = 0; loop < num; ++loop) {
                if (!pg_IntFromObjIndex(type, loop, &val))
                    return RAISE(
                        PyExc_TypeError,
                        "type sequence must contain valid event types");
                mask |= SDL_EVENTMASK(val);
            }
        }
        else if (pg_IntFromObj(type, &val))
            mask = SDL_EVENTMASK(val);
        else
            return RAISE(PyExc_TypeError,
                         "peek type must be numeric or a sequence");
    }

    SDL_PumpEvents();
    result = SDL_PeepEvents(&event, 1, SDL_PEEKEVENT, mask);

    if (noargs)
        return pgEvent_New(&event);
    return PyInt_FromLong(result == 1);
}
#else /* IS_SDLv2 */
static PyObject *
pg_event_peek(PyObject *self, PyObject *args)
{
    SDL_Event event;
    int result;
    int loop, num;
    PyObject *type;
    int val;

    if (PyTuple_Size(args) != 0 && PyTuple_Size(args) != 1)
        return RAISE(PyExc_ValueError, "peek requires 0 or 1 argument");

    VIDEO_INIT_CHECK();

    SDL_PumpEvents();

    if (PyTuple_Size(args) == 0) {
        if (SDL_PeepEvents(&event, 1, SDL_PEEKEVENT, SDL_FIRSTEVENT, SDL_LASTEVENT) < 0)
            return RAISE(pgExc_SDLError, SDL_GetError());
        return pgEvent_New(&event);
    }

    type = PyTuple_GET_ITEM(args, 0);
    if (PySequence_Check(type)) {
        num = PySequence_Size(type);
        for (loop = 0; loop < num; ++loop) {
            if (!pg_IntFromObjIndex(type, loop, &val))
                return RAISE(
                    PyExc_TypeError,
                    "type sequence must contain valid event types");
            result = SDL_PeepEvents(&event, 1, SDL_PEEKEVENT, val, val);
            if (result < 0) {
                return RAISE(pgExc_SDLError, SDL_GetError());
            } else if (result == 1) {
                return PyInt_FromLong(1);
            }
        }
    }
    else if (pg_IntFromObj(type, &val)) {
        result = SDL_PeepEvents(&event, 1, SDL_PEEKEVENT, val, val);
        if (result < 0)
            return RAISE(pgExc_SDLError, SDL_GetError());
        return PyInt_FromLong(result == 1);
    }
    return RAISE(PyExc_TypeError,
                 "peek type must be numeric or a sequence");
}
#endif /* IS_SDLv2 */

static PyObject *
pg_event_post(PyObject *self, PyObject *args)
{
    pgEventObject *e;
    SDL_Event event;
    int isblocked = 0;

    if (!PyArg_ParseTuple(args, "O!", &pgEvent_Type, &e))
        return NULL;

    VIDEO_INIT_CHECK();

    /* see if the event is blocked before posting it. */
    isblocked = SDL_EventState(e->type, SDL_QUERY) == SDL_IGNORE;

    if (isblocked) {
        /* event is blocked, so we do not post it. */
        Py_RETURN_NONE;
    }

    if (pgEvent_FillUserEvent(e, &event))
        return NULL;

messages.reasoning_content:
Now I understand the issue. This is pygame. Let me understand:

1. **`event.get(type)` should return posted matching events without a TypeError**: In the SDLv2 version of `pg_event_get`, when `type` is a single integer (not a sequence), the code does:
   ```c
   else if (pg_IntFromObj(type, &val)) {
       if (SDL_PeepEvents(&event, 1, SDL_GETEVENT, val, val) < 0) {
           ...
       }
       if(!_pg_event_append_to_list(list, &event))
           return NULL;
   }
   ```
   Then after this block:
   ```c
   Py_DECREF(list);
   return RAISE(PyExc_TypeError,
                "get type must be numeric or a sequence");
   ```

   Wait, that's buggy! For a single integer type, after appending, it falls through to `Py_DECREF(list); return RAISE(...)`. The `else if (pg_IntFromObj(...))` branch doesn't `return list`. So when you call `event.get(pygame.KEYDOWN)`, it appends the event and then raises a TypeError. Also, if no event is present, `SDL_PeepEvents` returns 0 and `pgEvent_New` is called on uninitialized event... Actually `_pg_event_append_to_list` calls `pgEvent_New(event)` even if `SDL_PeepEvents` returns 0 (no event). That could be a problem too.

   Let me re-read:
   ```c
   else if (pg_IntFromObj(type, &val)) {
       if (SDL_PeepEvents(&event, 1, SDL_GETEVENT, val, val) < 0) {
           Py_DECREF(list);
           return RAISE(pgExc_SDLError, SDL_GetError());
       }
       if(!_pg_event_append_to_list(list, &event))
           return NULL;
   }
   ```
   It ignores the return value of `SDL_PeepEvents`. If there are no matching events, `event` is uninitialized and `pgEvent_New` is called on it. That's a bug too. But the PR says "event.get(type) should return posted matching events without a TypeError". So the fix is to return the list after handling the integer case (and probably only append if there is an event).

   Actually, this is the known pygame bug. Let me check the actual pygame fix. The fix changed `pg_event_get` for SDLv2 to:
   ```c
   else if (pg_IntFromObj(type, &val)) {
       result = SDL_PeepEvents(&event, 1, SDL_GETEVENT, val, val);
       if (result < 0) {
           Py_DECREF(list);
           return RAISE(pgExc_SDLError, SDL_GetError());
       }
       if (result == 1) {
           if(!_pg_event_append_to_list(list, &event))
               return NULL;
       }
   }
   return list;
   ```

   And the sequence case has a similar issue: it should return the list after the loop, not raise. Currently:
   ```c
   if (PySequence_Check(type)) {
       num = PySequence_Size(type);
       for (loop = 0; loop < num; ++loop) {
           ...
           if (SDL_PeepEvents(&event, 1, SDL_GETEVENT, val, val) < 0) {
               ...
           }
           if(!_pg_event_append_to_list(list, &event))
               return NULL;
       }
   }
   ```
   It appends even when SDL_PeepEvents returns 0 (uninitialized event). And after the branch, falls through to the TypeError. So sequences also raise TypeError currently! The PR says "get(type) should return posted matching events without a TypeError" - this likely applies to both single and sequence types.

2. **`peek()` on an empty queue should be false**: In SDLv2 `pg_event_peek` with no args:
   ```c
   if (PyTuple_Size(args) == 0) {
       if (SDL_PeepEvents(&event, 1, SDL_PEEKEVENT, SDL_FIRSTEVENT, SDL_LASTEVENT) < 0)
           return RAISE(pgExc_SDLError, SDL_GetError());
       return pgEvent_New(&event);
   }
   ```
   If there are no events, SDL_PeepEvents returns 0, and `event` is uninitialized. `pgEvent_New` on uninitialized event. The PR says "peek() on an empty queue should be false". So the no-args peek should return `PyInt_FromLong(0)` (False) if no event. Actually maybe it should return False when there's no event, and the event object when there is one? Let me check docs/tests.

Let me look at the tests to understand expected behavior.

